  function scanSkillFiles(files) {
    const findings = [];
    for (const f of files) {
      const lines = f.text.split("\n");
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        for (const rule of RULES) {
          if (rule.pattern.test(line)) {
            findings.push({
              severity: rule.severity,
              file: f.path,
              line: i + 1,
              description: rule.description
            });
          }
        }
      }
      const blob = f.text.match(/[A-Za-z0-9+/]{400,}={0,2}/);
      if (blob) {
        findings.push({
          severity: "caution",
          file: f.path,
          line: null,
          description: `Large opaque base64 blob (${blob[0].length} chars)`
        });
      }
    }
    const verdict = findings.some((f) => f.severity === "dangerous") ? "dangerous" : findings.length > 0 ? "caution" : "safe";
    return { verdict, findings };
  }
