  // src/settings/modals/mcp-catalog.ts
  var McpCatalogModal = class extends Modal {
    constructor(app2, plugin2, onInstalled) {
      super(app2);
      this.plugin = plugin2;
      this.onInstalled = onInstalled;
    }
    onOpen() {
      this.renderList();
    }
    renderList() {
      const { contentEl } = this;
      contentEl.empty();
      contentEl.addClass("oa-confirm-modal");
      contentEl.createEl("h3", { text: "MCP catalog" });
      contentEl.createEl("p", {
        text: "Curated servers with pinned sources. Installing can clone and run third-party code on this device \u2014 only install servers you trust."
      });
      const list = contentEl.createDiv({ cls: "oa-hub-results" });
      for (const entry of MCP_CATALOG) {
        const installed = entry.name in this.plugin.settings.mcpServers;
        const row2 = list.createDiv({ cls: "oa-hub-row" });
        const main = row2.createDiv({ cls: "oa-hub-row-main" });
        main.createDiv({ cls: "oa-hub-row-name", text: entry.name });
        main.createDiv({ cls: "oa-hub-row-desc", text: entry.description });
        main.createDiv({
          cls: "oa-hub-row-src",
          text: `${entry.transport.type === "stdio" ? "stdio (command)" : "http (URL)"}${entry.install ? " \xB7 git install" : ""}${entry.auth.type === "api_key" ? " \xB7 needs API key" : entry.auth.type === "none" ? " \xB7 no auth" : ""}`
        });
        const actions = row2.createDiv({ cls: "oa-hub-row-actions" });
        if (installed) {
          actions.createDiv({ cls: "oa-hub-installed-badge", text: "installed" });
        }
        const btn = actions.createEl("button", { text: installed ? "Reinstall" : "Install" });
        btn.addEventListener("click", () => this.renderForm(entry));
      }
      const row = contentEl.createDiv({ cls: "oa-modal-actions" });
      const close = row.createEl("button", { text: "Close" });
      close.addEventListener("click", () => this.close());
    }
    renderForm(entry) {
      const { contentEl } = this;
