    /** One automation row: status dot, schedule/ledger meta, actions, run history. */
    cronRow(containerEl, task) {
      const s = this.plugin.settings;
      const running = this.plugin.isCronRunning(task.id);
      const completed = isCronCompleted(task) && !task.enabled;
      const status = running ? "running" : completed ? "completed" : !task.enabled ? "paused" : task.lastStatus === "error" ? "error" : task.lastRun > 0 ? "ok" : "idle";
      const taskCard = containerEl.createDiv({ cls: "oa-cron-task" });
      const setting = new Setting(taskCard);
      const nameFrag = document.createDocumentFragment();
      const dot = document.createElement("span");
      dot.className = `oa-cron-dot is-${status}`;
      const dotLabel = running ? "running now" : completed ? `completed after ${task.runCount} run${task.runCount === 1 ? "" : "s"}` : !task.enabled ? "paused" : task.lastStatus === "error" ? "last run failed" : task.lastRun > 0 ? "last run ok" : "scheduled, never run";
      dot.title = dotLabel;
      dot.setAttribute("role", "img");
      dot.setAttribute("aria-label", `Status: ${dotLabel}`);
      nameFrag.append(dot, document.createTextNode(` ${task.name}`));
      setting.setName(nameFrag);
      const descFrag = document.createDocumentFragment();
      const meta = document.createElement("div");
      const bits = [describeCronExpr(task.schedule.expr) ?? task.schedule.display, `\u2192 ${task.targetNote}`];
      if (completed)
        bits.push("completed");
      else if (task.enabled)
        bits.push(`next ${formatRelative(task.nextRun)}`);
      else
        bits.push("paused");
      bits.push(
        task.lastRun > 0 ? `last ${formatRelative(task.lastRun)}` : "never run",
        typeof task.maxRuns === "number" && task.maxRuns > 0 ? `${task.runCount}/${task.maxRuns} runs` : `${task.runCount} run${task.runCount === 1 ? "" : "s"}`
      );
      if (task.skills && task.skills.length > 0)
        bits.push(`skills ${task.skills.length}`);
      if (task.chainContext)
        bits.push("chain");
      if (task.notify)
        bits.push("notify");
      meta.textContent = bits.join(" \xB7 ");
      descFrag.appendChild(meta);
      if (task.lastStatus === "error" && task.lastError) {
        const err = document.createElement("div");
        err.className = "oa-cron-last-error";
        err.textContent = task.lastError;
        descFrag.appendChild(err);
      }
      setting.setDesc(descFrag);
      setting.addToggle(
        (t) => t.setValue(task.enabled).onChange(async (v) => {
          task.enabled = v;
          if (v)
