        (b) => b.setIcon("play").setTooltip("Run now").onClick(() => void this.plugin.runCronTask(task.id, true))
      ).addExtraButton(
        (b) => b.setIcon("pencil").setTooltip("Edit").onClick(() => {
          this.editingCronId = task.id;
          this.display();
        })
      ).addExtraButton(
        (b) => b.setIcon("history").setTooltip("Run history").onClick(() => {
          if (this.cronHistoryOpen.has(task.id))
            this.cronHistoryOpen.delete(task.id);
          else
            this.cronHistoryOpen.add(task.id);
          this.display();
        })
      ).addExtraButton(
        (b) => b.setIcon("trash-2").setTooltip("Delete").onClick(async () => {
          s.cronTasks = s.cronTasks.filter((t) => t.id !== task.id);
          if (this.editingCronId === task.id)
            this.editingCronId = null;
          this.cronHistoryOpen.delete(task.id);
          this.plugin.saveSettingsSafe();
          this.display();
        })
      );
      if (this.cronHistoryOpen.has(task.id))
        this.cronHistory(taskCard, task);
