    );
    const head = new Setting(containerEl).setName("Prompt commands").setDesc("New commands start visible on all three surfaces (Copilot parity); untick a column to hide one.");
    let restoreArmed = false;
    head.addButton(
      (b) => b.setButtonText("Restore defaults").onClick(async () => {
