  function renderCommandRows(ctx, list) {
    const s = ctx.plugin.settings;
    list.empty();
    if (s.promptSnippets.length === 0) {
      ctx.emptyState(list, {
        title: "No commands yet",
        description: "\u201CAdd command\u201D writes one \u2014 the composer \u201C+\u201D menu and / menu stay empty until then."
      });
      return;
    }
    let draggingIdx = null;
    const clearDropTargets = () => {
      for (const el of Array.from(list.querySelectorAll(".oa-snippet-row"))) {
        el.removeClass("is-drop-before");
        el.removeClass("is-drop-after");
      }
    };
    s.promptSnippets.forEach((snip, idx) => {
      const row = list.createDiv({ cls: "oa-snippet-row" });
      const grip = row.createDiv({ cls: "oa-cmd-grip", attr: { "aria-hidden": "true" } });
      grip.draggable = true;
      setIcon(grip, "grip-vertical");
      grip.addEventListener("dragstart", (e) => {
        draggingIdx = idx;
        row.addClass("is-dragging");
        if (e.dataTransfer) {
          e.dataTransfer.effectAllowed = "move";
          e.dataTransfer.setData("text/plain", String(idx));
        }
      });
      grip.addEventListener("dragend", () => {
        draggingIdx = null;
        clearDropTargets();
        row.removeClass("is-dragging");
      });
      row.addEventListener("dragover", (e) => {
        if (draggingIdx === null || draggingIdx === idx)
          return;
        e.preventDefault();
        if (e.dataTransfer)
          e.dataTransfer.dropEffect = "move";
        clearDropTargets();
        const rect = row.getBoundingClientRect();
        row.addClass(e.clientY < rect.top + rect.height / 2 ? "is-drop-before" : "is-drop-after");
      });
      row.addEventListener("drop", async (e) => {
        e.preventDefault();
        if (draggingIdx === null || draggingIdx === idx)
          return;
        const rect = row.getBoundingClientRect();
        const target = e.clientY < rect.top + rect.height / 2 ? idx : idx + 1;
        const [moved] = s.promptSnippets.splice(draggingIdx, 1);
        s.promptSnippets.splice(target, 0, moved);
        draggingIdx = null;
        clearDropTargets();
        await ctx.plugin.saveSettings();
        renderCommandRows(ctx, list);
      });
      const order = row.createDiv({ cls: "oa-cmd-order" });
      const mkArrow = (dir, target) => {
        const btn = order.createEl("button", {
          cls: "oa-icon-btn",
          attr: { "aria-label": `Move \u201C${snip.title}\u201D ${dir}`, title: `Move ${dir}` }
        });
        setIcon(btn, dir === "up" ? "chevron-up" : "chevron-down");
        if (target < 0 || target > s.promptSnippets.length - 1)
          btn.disabled = true;
        btn.onclick = async () => {
          const [moved] = s.promptSnippets.splice(idx, 1);
          s.promptSnippets.splice(target, 0, moved);
          await ctx.plugin.saveSettings();
          renderCommandRows(ctx, list);
        };
      };
      mkArrow("up", idx - 1);
      mkArrow("down", idx + 1);
      const main = row.createDiv({ cls: "oa-snippet-main" });
      main.createDiv({ cls: "oa-snippet-title", text: snip.title });
      main.createDiv({ cls: "oa-snippet-text", text: snip.text });
      const surfaces = [];
      if (snip.ctxMenu === true)
        surfaces.push("menu");
      if (snip.slash === true)
        surfaces.push("slash");
      if (snip.picker !== false)
        surfaces.push("+");
      if (snip.quickAsk === true)
        surfaces.push("quick ask");
      main.createDiv({
        cls: "oa-snippet-surfaces",
        text: surfaces.length ? `Shows in: ${surfaces.join(" \xB7 ")}` : "Not shown anywhere"
      });
      const actions = row.createDiv({ cls: "oa-snippet-actions" });
      const edit = actions.createEl("button", {
        cls: "oa-icon-btn",
        attr: { "aria-label": `Edit command \u201C${snip.title}\u201D`, title: "Edit" }
      });
      setIcon(edit, "pencil");
      edit.onclick = () => new SnippetEditModal(ctx.app, snip, async (updated) => {
        const i = s.promptSnippets.findIndex((x) => x.id === snip.id);
        if (i >= 0)
          s.promptSnippets[i] = updated;
        await ctx.plugin.saveSettings();
        renderCommandRows(ctx, list);
      }).open();
      const dupe = actions.createEl("button", {
        cls: "oa-icon-btn",
        attr: { "aria-label": `Duplicate command \u201C${snip.title}\u201D`, title: "Duplicate" }
      });
      setIcon(dupe, "copy-plus");
      dupe.onclick = async () => {
        s.promptSnippets.splice(idx + 1, 0, { ...snip, id: newSnippetId(), title: `${snip.title} copy` });
        await ctx.plugin.saveSettings();
        renderCommandRows(ctx, list);
      };
      const del = actions.createEl("button", {
        cls: "oa-icon-btn",
        attr: { "aria-label": `Delete command \u201C${snip.title}\u201D`, title: "Delete" }
      });
      setIcon(del, "trash-2");
      let armed = false;
      del.onclick = async () => {
        if (!armed) {
          armed = true;
          del.addClass("is-armed");
          del.setAttribute("title", "Click again to delete");
          window.setTimeout(() => {
            armed = false;
            del.removeClass("is-armed");
            del.setAttribute("title", "Delete");
          }, 2500);
          return;
        }
        s.promptSnippets = s.promptSnippets.filter((x) => x.id !== snip.id);
        await ctx.plugin.saveSettings();
        renderCommandRows(ctx, list);
      };
    });
  }

  // src/settings/sections/terminal.ts
  function terminalSettings(ctx, containerEl) {
    const s = ctx.plugin.settings;
    if (Platform?.isDesktopApp !== true) {
      new Setting(containerEl).setName("Unavailable on mobile").setDesc("The plugin remains mobile-capable, but terminal/process schemas and the Node runtime are not registered on mobile.");
      return;
    }
    const enabled = new Setting(containerEl).setName("Enable Terminal & Processes").setDesc("Off by default. Every command start shows a frozen command/backend/image/Workspace/cwd/timeout preview and only supports Allow once.").addToggle((toggle) => toggle.setValue(s.toolsets.terminal).onChange(async (value) => {
      if (!value) {
        s.toolsets.terminal = false;
        ctx.plugin.saveSettingsSafe();
        return;
      }
      if (s.terminal.consentVersion !== 1) {
        toggle.setValue(false);
        new TerminalConsentModal(ctx.app, async () => {
          await ctx.plugin.grantTerminalConsent();
          ctx.display();
        }).open();
        return;
      }
      s.toolsets.terminal = true;
      ctx.plugin.saveSettingsSafe();
    }));
    markModified(enabled, ctx.plugin.settings, "toolsets.terminal");
    const backend = new Setting(containerEl).setName("Execution backend").setDesc("Docker is recommended. Local is an unsandboxed expert path and never supports background processes.").addDropdown((dropdown) => dropdown.addOption("docker", "Docker \u2014 disposable, network off").addOption("local", "Local \u2014 expert, foreground only").setValue(s.terminal.backend).onChange(async (value) => {
      s.terminal.backend = value === "local" ? "local" : "docker";
      ctx.plugin.saveSettingsSafe();
      ctx.display();
    }));
    markModified(backend, ctx.plugin.settings, "terminal.backend");
    if (s.terminal.backend === "docker") {
      const image = new Setting(containerEl).setName("Docker image").setDesc("Chosen by Settings, never by the agent. Commands run with no network, a read-only root, resource caps, closed stdin, and a masked Workspace.").addText((text) => text.setPlaceholder("repository:tag or repository@digest").setValue(s.terminal.dockerImage).onChange(async (value) => {
        const next = value.trim();
        if (!next || next.length > 256 || /[\u0000-\u001f\u007f\s]/.test(next) || next.startsWith("-")) {
          new Notice("Open Agent: enter a valid Docker image reference without whitespace or control characters.");
          text.setValue(s.terminal.dockerImage);
          return;
        }
        s.terminal.dockerImage = next;
        ctx.plugin.saveSettingsSafe();
      }));
      markModified(image, ctx.plugin.settings, "terminal.dockerImage");
    } else {
      const expert = new Setting(containerEl).setName("I understand Local is not sandboxed").setDesc("Required separately. Local is refused in YOLO and Strict Workspace, is foreground-only, and can reach anything Obsidian can.").addToggle((toggle) => toggle.setValue(s.terminal.localExpertEnabled).onChange(async (value) => {
        s.terminal.localExpertEnabled = value;
        ctx.plugin.saveSettingsSafe();
      }));
      markModified(expert, ctx.plugin.settings, "terminal.localExpertEnabled");
    }
    new Setting(containerEl).setName("Backend health").setDesc("Checks Docker Engine availability or reports the host-shell runtime. It does not run an agent command.").addButton((button) => button.setButtonText("Check health").onClick(async () => {
      button.setDisabled(true).setButtonText("Checking\u2026");
      try {
        const result = await ctx.plugin.runner.terminalHealth(ctx.plugin.settings);
        new Notice(`Open Agent: ${result.ok ? "ready" : "not ready"} \u2014 ${result.message}`, 8e3);
      } finally {
        button.setDisabled(false).setButtonText("Check health");
      }
    }));
    new Setting(containerEl).setName("Stop all owned processes").setDesc("Stops every command this plugin started. Also runs on unload and security-setting changes.").addButton((button) => button.setWarning().setButtonText("Stop all").onClick(async () => {
      button.setDisabled(true);
      try {
        const stopped = await ctx.plugin.runner.stopAllTerminal();
        new Notice(`Open Agent: stop requested for ${stopped} command${stopped === 1 ? "" : "s"}.`);
      } finally {
        button.setDisabled(false);
      }
    }));
  }

