      const stMaxTokens = new Setting(containerEl).setName("Max output tokens").setDesc("Maximum tokens per reply \u2014 0 lets the provider decide. The slider sweeps coarse values; type any number for exact control.");
      stMaxTokens.controlEl.appendChild(
