      const embedStatus = embedSaved ? `${embedSavedProvider ? embedSavedProvider.name : "chat provider"} \xB7 ${embedSaved}` : "off (keyword recall only)";
      const embedPickProvider = s.providers.some((p) => p.id === this.embedPickProviderId) ? this.embedPickProviderId : s.memoryEngineEmbedProviderId || s.activeProviderId;
      const embedPickModel = this.embedPickModel ?? embedSaved;
      const embedSetting = new Setting(containerEl).setName("Embedding model").setDesc(`Pick a model to enable semantic recall \u2014 currently ${embedStatus}. Providers are set up in the Providers tab.`);
      const embedCtl = stackedControl(embedSetting, { row: true });
      const usableEmbedProviders = s.providers.filter((p) => providerUsable(p));
      const embedProvDd = new DropdownComponent(embedCtl);
      if (usableEmbedProviders.length === 0)
        embedProvDd.addOption("", "(configure a provider first)");
      for (const p of usableEmbedProviders)
        embedProvDd.addOption(p.id, p.name);
      if (embedPickProvider && !usableEmbedProviders.some((p) => p.id === embedPickProvider)) {
