      const stTitleGen = new Setting(containerEl).setName("Title generation").setDesc("Name new sessions automatically after the first reply. Off by default \u2014 it costs one extra request per new session.").addToggle(
        (t) => t.setValue(s.titleGenerationEnabled).onChange(async (v) => {
